/**
 * Extracts the official UX4G design tokens from the installed
 * ux4g-web-components package into src/styles/ux4g-tokens.css.
 *
 * Only the token declarations are taken: the package's full stylesheet also
 * carries a global reset and several thousand utility classes, which would
 * collide with the application's existing Tailwind layer. Values are copied
 * verbatim from the package, never retyped, so the tokens stay official and
 * can be regenerated by running:  bun scripts/extract-ux4g-tokens.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const pkgJson = require("ux4g-web-components/package.json");
const cssPath = require.resolve("ux4g-web-components/styles.css");
const css = readFileSync(cssPath, "utf8");

/** Collects the --ux4g-* declarations from every rule using the given selector. */
function tokensFor(selector) {
  const out = [];
  let i = 0;
  while (true) {
    const at = css.indexOf(`${selector}{`, i);
    if (at === -1) break;
    const start = at + selector.length + 1;
    const end = css.indexOf("}", start);
    const body = css.slice(start, end);
    for (const decl of body.split(";")) {
      if (decl.trim().startsWith("--ux4g-")) out.push(decl.trim());
    }
    i = end + 1;
  }
  return out;
}

const root = tokensFor(":root");
const dark = tokensFor("[data-theme=dark]");

if (root.length < 100) throw new Error(`Expected UX4G root tokens, found ${root.length}`);

const block = (decls) => decls.map((d) => `  ${d};`).join("\n");

const output = `/*
 * UX4G design tokens — generated file, do not edit by hand.
 *
 * Source: ux4g-web-components@${pkgJson.version} (styles/ux4g.css), the
 * official UX4G Design System package. Regenerate with:
 *   bun scripts/extract-ux4g-tokens.mjs
 *
 * ${root.length} root tokens, ${dark.length} dark-theme tokens. Values are copied
 * verbatim. The application maps its semantic tokens onto these in styles.css.
 */

:root {
${block(root)}
}

[data-theme="dark"],
.dark {
${block(dark)}
}
`;

mkdirSync("src/styles", { recursive: true });
writeFileSync("src/styles/ux4g-tokens.css", output);
console.log(
  `Wrote src/styles/ux4g-tokens.css from ux4g-web-components@${pkgJson.version}: ${root.length} root tokens, ${dark.length} dark tokens.`,
);
